exercises.tests:
def test_cubes():
    assert cubes == [0, 1, 8, 27, 64], f"ожидалось [0, 1, 8, 27, 64], получено {cubes}"


def test_cubes_length():
    assert len(cubes) == 5, "cubes должен содержать ровно 5 чисел — для x от 0 до 4 включительно"

def test_successful_codes():
    assert successful_codes == [200, 200, 200], f"ожидалось [200, 200, 200], получено {successful_codes}"


def test_error_lines():
    assert error_lines == ["1: 404", "3: 500", "6: 403"], f"получено {error_lines}"

def test_mismatches():
    assert mismatches == ["expected 200, got 500"], f"получено {mismatches}"


def test_mismatches_count():
    assert len(mismatches) == 1, "из 4 пар не совпадает только одна — mismatches должен содержать ровно один элемент"

def test_cleaned():
    assert cleaned == [1, 3, 4, 5], f"ожидалось [1, 3, 4, 5], получено {cleaned}"


def test_original_not_mutated():
    assert numbers == [1, 2, 2, 3, 4, 2, 5], "исходный список numbers не должен быть изменён"
